/**
 * The differential test of the guarantee-or-abstain checkers (R12): the TypeScript port (shared/kernel/coverage.ts)
 * against the Python checker it was compared with (experiments/r11-portfolio/qpi/guarantee/checker.py), on requests
 * generated by fast-check (shared/kernel/coverageGen.ts; SYNTHETIC inputs only). The Python side runs once, in a batch,
 * through experiments/r11-portfolio/guarantee_wire.py.
 *
 *   node scripts/coverage-differential.ts [--n 3000] [--seed 20261124] [--record [--keep 240]]
 *
 * --record rewrites shared/kernel/coverage.fixtures.json: the 22 recorded research cases (rebuilt by guarantee_wire.py
 * export, each byte-identical to its file in results/guarantee/) and the first --keep generated cases, each with the
 * Python outcome reduced to the compared fields, which coverage.test.ts checks on every run without Python.
 *
 * Python runs in the workspace's environment: QED_QUANT_ENV, or envs/quant of the main checkout (found through git).
 */
import { spawnSync } from 'node:child_process'
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import fc from 'fast-check'
import { check, REFERENCE_VERSION } from '../shared/kernel/coverage.ts'
import { codes, compare, trim } from '../shared/kernel/coverageCompare.ts'
import { anyRequest } from '../shared/kernel/coverageGen.ts'

const arg = (name: string, d: string): string => { const i = process.argv.indexOf(`--${name}`); return i > 0 && process.argv[i + 1] && !process.argv[i + 1]!.startsWith('--') ? process.argv[i + 1]! : d }
const N = Number(arg('n', '3000')), SEED = Number(arg('seed', '20261124')), RECORD = process.argv.includes('--record'), KEEP = Number(arg('keep', '240'))
const APP = join(import.meta.dirname, '..')
const REPO = resolve(APP, '..', '..')
const WIRE = join(REPO, 'experiments', 'r11-portfolio', 'guarantee_wire.py')
const common = spawnSync('git', ['-C', REPO, 'rev-parse', '--path-format=absolute', '--git-common-dir'], { encoding: 'utf8' }).stdout.trim()
const ENV = process.env.QED_QUANT_ENV ?? join(dirname(common), 'envs', 'quant')
const tmp = mkdtempSync(join(tmpdir(), 'qed-coverage-diff-'))

function python(...args: string[]): void {
  const r = spawnSync('uv', ['run', '--directory', ENV, 'python', '-I', WIRE, ...args], { encoding: 'utf8', maxBuffer: 1 << 28, env: { ...process.env, VECLIB_MAXIMUM_THREADS: '1' } })
  if (r.status !== 0) { console.error(r.stdout, r.stderr); throw new Error(`python ${args[0]} failed (exit ${r.status})`) }
}

const requests = fc.sample(anyRequest, { numRuns: N, seed: SEED }) as unknown[]
writeFileSync(join(tmp, 'in.json'), JSON.stringify(requests))
const t0 = Date.now()
python('oracle', join(tmp, 'in.json'), join(tmp, 'out.json'))
const tPy = Date.now() - t0
const outs = JSON.parse(readFileSync(join(tmp, 'out.json'), 'utf8')) as Record<string, unknown>[]
const t1 = Date.now()
interface Row { i: number; type: string; py: Record<string, unknown>; ts: ReturnType<typeof check>; hard: string[]; codesAgree: boolean; deliberate: string | null; exposure: boolean }
const rows: Row[] = requests.map((req, i) => {
  const py = outs[i]!, ts = check(req), type = (req as { type: string }).type
  if (py.error) return { i, type, py, ts, hard: [`python raised ${String(py.error)}`], codesAgree: false, deliberate: null, exposure: false }
  const c = compare(py, ts)
  return { i, type, py, ts, hard: c.hard, codesAgree: c.codesAgree, deliberate: c.deliberate, exposure: c.exposure }
})
const tTs = Date.now() - t1
const tally = new Map<string, { n: number; full: number; hard: number; codes: number; deliberate: number }>()
for (const r of rows) {
  const key = `${r.type} ${String(r.py.status ?? 'python error')}`
  const t = tally.get(key) ?? { n: 0, full: 0, hard: 0, codes: 0, deliberate: 0 }
  t.n++
  if (r.hard.length) t.hard++; else if (r.deliberate) t.deliberate++; else if (!r.codesAgree) t.codes++; else t.full++
  tally.set(key, t)
}
const hard = rows.filter((r) => r.hard.length), soft = rows.filter((r) => !r.hard.length && !r.deliberate && !r.codesAgree), deliberate = rows.filter((r) => !r.hard.length && r.deliberate), higher = rows.filter((r) => !r.hard.length && r.exposure)
console.log(`Generated ${N} requests (fast-check seed ${SEED}); Python ${REFERENCE_VERSION} took ${tPy} ms, TypeScript ${tTs} ms.`)
console.log('  python outcome                              all fields   only reason codes differ   deliberate status   hard difference')
for (const [k, v] of [...tally].sort()) console.log(`  ${k.padEnd(42)} ${String(v.full).padStart(10)} ${String(v.codes).padStart(26)} ${String(v.deliberate).padStart(19)} ${String(v.hard).padStart(17)}   of ${v.n}`)
console.log(`${N - hard.length - soft.length - deliberate.length - higher.filter((r) => r.codesAgree).length} of ${N} agree on every compared field; ${soft.length} differ only in which reason codes are named together; ${deliberate.length} differ in status by the port's deliberate sleeve rules (RISKY_SLEEVE_TOO_LARGE, RISKY_SLEEVE_CURRENCY); ${higher.length} where the port's in-transit exposure is higher (due date, not funding deadline); ${hard.length} hard differences.`)
for (const b of hard.slice(0, 12)) { console.log(`--- HARD #${b.i} (${b.type})`); for (const d of b.hard) console.log(`    ${d.slice(0, 400)}`); console.log(`    request: ${JSON.stringify(requests[b.i]).slice(0, 1500)}`) }
const cats = new Map<string, number>()
for (const r of soft) { const k = `${r.type}: python [${codes(r.py).join(', ')}] port [${codes(r.ts).join(', ')}]`; cats.set(k, (cats.get(k) ?? 0) + 1) }
if (cats.size) { console.log('Reason-code differences (both abstain):'); for (const [k, n] of [...cats].sort((a, b) => b[1] - a[1]).slice(0, 15)) console.log(`  ${String(n).padStart(4)}  ${k}`) }

if (RECORD) {
  python('export', join(tmp, 'recorded.json'))
  const rec = JSON.parse(readFileSync(join(tmp, 'recorded.json'), 'utf8')) as { checker_version: string; cases: { name: string; request: unknown; outcome: Record<string, unknown> }[] }
  if (hard.length) throw new Error('hard differences: nothing recorded')
  const pin = (r: Row) => ({ request: requests[r.i], expect: trim(r.py), ...(r.deliberate ? { port: { status: r.ts.status, codes: codes(r.ts), why: `deliberate: ${r.deliberate}` } } : !r.codesAgree ? { port: { codes: codes(r.ts), why: 'reason precedence' } } : r.exposure ? { port: { exposure: true, why: 'in-transit exposure counted to the due date' } } : {}) })
  const first = rows.slice(0, KEEP)
  const extra = [...deliberate, ...higher, ...soft].filter((r) => r.i >= KEEP).slice(0, 60)
  const keep = [...first, ...extra].map(pin)
  for (const c of rec.cases) { const cmp = compare(c.outcome, check(c.request)); if (cmp.hard.length || !cmp.codesAgree) throw new Error(`recorded case ${c.name} does not agree: ${cmp.hard.join('; ')}`) }
  const file = join(APP, 'shared', 'kernel', 'coverage.fixtures.json')
  writeFileSync(file, `${JSON.stringify({
    note: 'Python checker outcomes (reduced to the compared fields) for the 22 recorded research requests and for generated SYNTHETIC requests; where the port names other reason codes, or refuses by its deliberate rule, its answer is pinned beside Python\'s. Written by scripts/coverage-differential.ts --record; checked by coverage.test.ts.',
    python_checker: rec.checker_version, fast_check_seed: SEED, generated_of: N,
    recorded: rec.cases.map((c) => ({ name: c.name, request: c.request, expect: trim(c.outcome) })),
    generated: keep,
  })}\n`)
  console.log(`Recorded ${rec.cases.length} research cases and ${keep.length} generated cases (${keep.filter((k) => 'port' in k).length} with the port's answer pinned) in ${file}.`)
}
process.exitCode = hard.length ? 1 : 0
